#!/usr/bin/env bash
# Chapitre « Les documents légaux et les données personnelles » (partie Légal et RGPD) + sommaire.
# Prérequis : apply-docs-demandes.sh.
# Usage (racine du repo) : bash apply-docs-legal-donnees.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/legal/documents-legaux-et-donnees.mdx" 2>/dev/null | grep -qF "title: \"Les documents légaux et les données personnelles\""; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "title: \"Les demandes\"" "apps/web/content/docs/dev/membres/demandes.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-demandes.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/index.mdx")
CREATED=("apps/web/content/docs/dev/legal/documents-legaux-et-donnees.mdx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "apps/web/content/docs/dev/legal" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "title: \"Les documents légaux et les données personnelles\"" "apps/web/content/docs/dev/legal/documents-legaux-et-donnees.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/legal"
